package spotifyclean

import (
	"encoding/hex"
	"testing"
)

func TestBlockTransformReference(t *testing.T) {
	stateData, err := hex.DecodeString("")
	if err != nil {
		t.Fatal(err)
	}
	expected, err := hex.DecodeString("cb3f49bec42ecd91d2beaf0086e5ca7d")
	if err != nil {
		t.Fatal(err)
	}
	var state [744]byte
	copy(state[:], stateData)
	var out [16]byte
	blockTransform(&state, &out)
	if string(out[:]) != string(expected) {
		t.Fatalf("counter mismatch: got %x, expected %x", out, expected)
	}
}
